lib_code = '''from collections import defaultdict, deque

def components(grid, connectivity=8):
    """The connected components as (color, cells) for each nonzero color."""
    seen = set(); out = []
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] and (i, j) not in seen:
                c = grid[i][j]; q = [(i, j)]; seen.add((i, j)); cells = []
                while q:
                    y, x = q.pop(); cells.append((y, x))
                    for dy in (-1, 0, 1):
                        for dx in (-1, 0, 1):
                            if abs(dy) + abs(dx) > connectivity: continue
                            a, b = y + dy, x + dx
                            if 0 <= a < len(grid) and 0 <= b < len(grid[0]) and grid[a][b] == c and (a, b) not in seen:
                                seen.add((a, b)); q.append((a, b))
                out.append((c, cells))
    return out

def pattern_key(cells):
    """A translation-invariant key: the sorted cell offsets from the top-left corner."""
    ys = [c[0] for c in cells]; xs = [c[1] for c in cells]
    return tuple(sorted((y - min(ys), x - min(xs)) for y, x in cells))

def recolor_by_pattern(grid, source=1):
    """Every component of color source takes the color of the component with the identical cell pattern."""
    comps = components(grid)
    bypat = defaultdict(list)
    for c, cells in comps: bypat[pattern_key(cells)].append((c, cells))
    out = [row[:] for row in grid]
    for c, cells in comps:
        if c == source:
            others = [cc for cc, cel in bypat[pattern_key(cells)] if cc != source]
            if others:
                for y, x in cells: out[y][x] = others[0]
    return out
'''
